/* Generated from the shared neutral palette and Liquid primitives. */
:root {
  color-scheme: light;

  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
  --heading-weight: 600;
  --container: 1280px;
  --section-gap: 64px;
  --header-height: 64px;
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
  --shadow-x: 0;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0;
  --shadow-opacity: 0.1;
  --shadow-color: oklch(0 0 0);
  --shadow-2xs: 0 1px 3px 0 hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0 hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0 hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0 hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md: 0 1px 3px 0 hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg: 0 1px 3px 0 hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl: 0 1px 3px 0 hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0 hsl(0 0% 0% / 0.25);
  --font-sans: 'Geist', ui-sans-serif, system-ui, sans-serif;
  --font-heading: var(--font-sans);
  --font-mono: ui-monospace, sfmono-regular, menlo, monaco, consolas, monospace;
  --tracking-tight: -0.025em;
  --tracking-normal: 0;
  --spacing: 0.25rem;
  --gutter: calc(var(--spacing) * 4);
  --section-padding: calc(var(--spacing) * 16);
  --on-media: #fff;
  --on-media-muted: rgb(255 255 255 / 0.85);
  --media-button: #fff;
  --media-button-foreground: #171717;
  --media-button-hover: #e5e5e5;
  --media-secondary: rgb(255 255 255 / 0.15);
  --media-secondary-hover: rgb(255 255 255 / 0.2);
  --media-overlay: rgb(0 0 0 / 0.7);
  --media-base: rgb(0 0 0);
  --media-fade: linear-gradient(to top, rgb(0 0 0 / 0.8), rgb(0 0 0 / 0.6));
  --scrim: rgb(0 0 0 / 0.1);
  --focus-ring: 0 0 0 3px color-mix(in oklch, var(--ring) 50%, transparent);
}
.dark {
  color-scheme: dark;

  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
  --focus-ring: 0 0 0 3px color-mix(in oklch, var(--ring) 50%, transparent);
}

{% doc %}
  Fulldev UI base styles. Use native markup with its data-slot parts.
{% enddoc %}

{% stylesheet %}
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    border-color: var(--border);
  }
  body {
    margin: 0;
    min-height: 100svh;
    display: flex;
    flex-direction: column;
    background: var(--background);
    color: var(--foreground);
    font: 16px/1.5 var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizelegibility;
  }
  main {
    flex: 1;
  }
  img,
  video,
  svg,
  iframe {
    max-width: 100%;
  }
  img,
  video,
  svg {
    display: block;
    height: auto;
  }
  a {
    color: inherit;
    text-decoration: none;
    text-underline-offset: 4px;
  }
  button,
  input,
  select,
  textarea {
    font: inherit;
    color: inherit;
  }
  button,
  summary {
    cursor: pointer;
  }
  button {
    border: 0;
    background: none;
    padding: 0;
    border-radius: 0;
  }
  :focus-visible {
    outline: 2px solid color-mix(in oklch, var(--ring) 50%, transparent);
    outline-offset: 2px;
  }
  [hidden] {
    display: none !important;
  }
  h1,
  h2,
  h3,
  h4,
  p,
  figure,
  blockquote,
  fieldset,
  dl,
  dd {
    margin: 0;
  }
  fieldset {
    border: 0;
    padding: 0;
    min-width: 0;
  }
  /* Lists that a part or layout styles with a class; merchant rich text keeps its markers. */
  :where(ul, ol)[class] {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  legend {
    padding: 0;
  }
  p,
  h1,
  h2,
  h3,
  h4,
  a,
  li {
    overflow-wrap: anywhere;
  }
{% endstylesheet %}

{% doc %}
  Fulldev UI tokens and native base. Render once in the head before theme overrides.
{% enddoc %}

{{ 'ui-tokens.css' | asset_url | stylesheet_tag: preload: true }}
